+/** Picks `ko` or `en` from an Accept-Language header by q-value; `fallback` if neither is listed. */
+export function pickLanguage(header, fallback = "en") {
+  if (typeof header !== "string") return fallback;
+  const ranked = header
+    .split(",")
+    .map((part, i) => {
+      const [tag, ...attrs] = part.trim().split(";");
+      const qAttr = attrs.map((a) => a.trim()).find((a) => /^q=/i.test(a));
+      const q = qAttr ? Number(qAttr.slice(2)) : 1;
+      return { lang: tag.trim().toLowerCase().split("-")[0], q: Number.isNaN(q) ? 0 : q, i };
+    })
+    .filter((c) => c.q > 0 && LANGUAGES.includes(c.lang))
+    .sort((a, b) => b.q - a.q || a.i - b.i);
+  return ranked.length ? ranked[0].lang : fallback;
+}
